import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const l="/assets/settings-menu.CNsvqeOQ.png",i="/assets/about-diagnostics.B5iJqv67.png",m=JSON.parse('{"title":"设置与帮助","description":"","frontmatter":{},"headers":[],"relativePath":"08-settings-and-help.md","filePath":"zh-CN/08-settings-and-help.md"}'),n={name:"08-settings-and-help.md"};function s(h,a,d,c,p,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="设置与帮助" tabindex="-1">设置与帮助 <a class="header-anchor" href="#设置与帮助" aria-label="Permalink to &quot;设置与帮助&quot;">​</a></h1><p>调整使用体验、检查更新，并解决常见问题。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>切换界面语言、字体、字号和界面大小。</li><li>管理隐藏列、拼写检查和机器翻译预设。</li><li>检查更新、进入授权管理和清理缓存。</li><li>查看快捷键、版本、许可证和临时诊断。</li></ul><h2 id="切换界面语言" tabindex="-1">切换界面语言 <a class="header-anchor" href="#切换界面语言" aria-label="Permalink to &quot;切换界面语言&quot;">​</a></h2><p>打开 <strong>设置 → 界面语言</strong>，选择 <strong>中文</strong> 或 <strong>English</strong>。语言偏好保存在本机，下次启动时自动恢复。</p><p>如果某项中文文案缺失，应用可能回退到英文；正常界面不应显示类似内部键名的文本。</p><h2 id="调整字体和字号" tabindex="-1">调整字体和字号 <a class="header-anchor" href="#调整字体和字号" aria-label="Permalink to &quot;调整字体和字号&quot;">​</a></h2><ul><li><strong>编辑器字体</strong>：选择表格文本使用的字体。</li><li><strong>表格字号</strong>：调整字幕单元格字号，最小为 12px。</li><li><strong>界面大小</strong>：按 5% 调整 50%–150% 的整体 UI 比例。</li></ul><p><img src="'+l+'" alt="设置菜单显示语言、字体、字号、界面大小和工具入口"></p><p>较小窗口或高 DPI 屏幕可适当降低界面大小，再拖动表格与视频面板之间的分隔条。960×600 是常规完整编辑体验的建议最低尺寸；840×480 用于保证紧急情况下核心控件仍可访问。</p><h2 id="显示或隐藏表格列" tabindex="-1">显示或隐藏表格列 <a class="header-anchor" href="#显示或隐藏表格列" aria-label="Permalink to &quot;显示或隐藏表格列&quot;">​</a></h2><p>启用 <strong>显示隐藏列</strong> 可查看默认隐藏的元数据列。关闭后只改变显示，不删除数据。使用 <strong>重置布局</strong> 可恢复列宽。</p><p>内部派生字段通常为只读；不要为了消除提示而直接修改自动计算列。</p><h2 id="管理拼写检查" tabindex="-1">管理拼写检查 <a class="header-anchor" href="#管理拼写检查" aria-label="Permalink to &quot;管理拼写检查&quot;">​</a></h2><ul><li><strong>检查译文拼写</strong>：启用或关闭当前工作区的译文拼写扫描。</li><li><strong>词典</strong>：安装、刷新和选择 Hunspell 词典，管理忽略词和用户词典。</li></ul><p>完整操作见<a href="./05-quality-checks.html#安装和切换拼写词典">质量检查</a>。</p><h2 id="管理机器翻译预设" tabindex="-1">管理机器翻译预设 <a class="header-anchor" href="#管理机器翻译预设" aria-label="Permalink to &quot;管理机器翻译预设&quot;">​</a></h2><ul><li><strong>机器翻译服务</strong>：管理连接、模型、能力和网络设置。</li><li><strong>机器翻译提示词</strong>：管理可复用的翻译指导。</li></ul><p>预设在应用级共享；当前项目保存最近选择。详细说明见<a href="./06-machine-translation.html">机器翻译</a>。</p><h2 id="检查和安装更新" tabindex="-1">检查和安装更新 <a class="header-anchor" href="#检查和安装更新" aria-label="Permalink to &quot;检查和安装更新&quot;">​</a></h2><p>Windows 与 macOS 均使用 <strong>检查更新</strong>。两平台独立发布，版本号可能不同，应用只接收适合当前系统和架构的更新；Mac 更新不会安装 Windows 包。安装前先保存项目。当前 Mac 测试版的完整跨版本升级仍在验收中；失败时可从发布方下载对应系统的新安装包。</p><p>点击 <strong>检查更新</strong>：</p><ul><li>已是最新版本时，在设置菜单中显示当前版本提示。</li><li>有更新时，弹窗显示新旧版本，可选择 <strong>稍后</strong> 或 <strong>安装更新</strong>。</li><li>下载和安装过程中会显示进度；完成后应用重新启动。</li></ul><p>自动检查失败通常保持安静；手动检查失败会显示错误，便于排查网络或发布端点。</p><h2 id="打开授权管理" tabindex="-1">打开授权管理 <a class="header-anchor" href="#打开授权管理" aria-label="Permalink to &quot;打开授权管理&quot;">​</a></h2><p>点击 <strong>设置 → 授权</strong>，可以查看当前状态、生成机器码、添加或移除授权。获取授权、适用范围、换机和故障处理见独立的<a href="./09-license-management.html">授权管理</a>。</p><h2 id="清除缓存并重启" tabindex="-1">清除缓存并重启 <a class="header-anchor" href="#清除缓存并重启" aria-label="Permalink to &quot;清除缓存并重启&quot;">​</a></h2><p>点击 <strong>清除缓存并重启</strong> 后，应用会要求确认；有未保存修改时会额外警告。</p><p>该操作清除应用拥有的本地 UI 缓存、旧版会话缓存和存储的文件句柄信息，然后重新加载应用。它不会成为删除项目文件夹的操作；项目模式的 <code>project.json</code>、<code>workspace.csv</code> 和项目草稿仍保留在磁盘。</p><p>执行前仍应正式保存重要工作。</p><h2 id="查看快捷键" tabindex="-1">查看快捷键 <a class="header-anchor" href="#查看快捷键" aria-label="Permalink to &quot;查看快捷键&quot;">​</a></h2><p>点击 <strong>快捷键</strong>，或按 <code>?</code> 打开帮助。对话框按编辑、表格和视频列出保存、撤销、查找、替换、播放、字幕导航和拼写检查快捷键。</p><p>详细表格见<a href="./01-getting-started.html#查看快捷键和操作帮助">开始使用</a>。</p><h2 id="查看版本和第三方许可" tabindex="-1">查看版本和第三方许可 <a class="header-anchor" href="#查看版本和第三方许可" aria-label="Permalink to &quot;查看版本和第三方许可&quot;">​</a></h2><p>点击 <strong>关于 GridSubStudio</strong> 查看：</p><ul><li>当前应用版本。</li><li>运行环境概要。</li><li>第三方组件、版本和许可证。</li><li>临时诊断开关。</li></ul><h2 id="启用和导出临时诊断" tabindex="-1">启用和导出临时诊断 <a class="header-anchor" href="#启用和导出临时诊断" aria-label="Permalink to &quot;启用和导出临时诊断&quot;">​</a></h2><p>临时诊断用于复现焦点、行选择、播放同步或滚动问题：</p><ol><li>打开 <strong>关于 GridSubStudio</strong>。</li><li>启用 <strong>临时诊断</strong>。</li><li>在当前工作区复现问题。</li><li>点击 <strong>导出诊断包</strong>。</li></ol><p><img src="'+i+'" alt="关于页面底部的临时诊断开关和导出诊断包按钮"></p><p>诊断只在当前工作区的有限内存缓冲中保存状态摘要，不记录字幕正文。切换项目、关闭工作区或关闭诊断时会清空。</p><h2 id="解决常见问题" tabindex="-1">解决常见问题 <a class="header-anchor" href="#解决常见问题" aria-label="Permalink to &quot;解决常见问题&quot;">​</a></h2><h3 id="macos-首次启动被拦截" tabindex="-1">macOS 首次启动被拦截 <a class="header-anchor" href="#macos-首次启动被拦截" aria-label="Permalink to &quot;macOS 首次启动被拦截&quot;">​</a></h3><p>当前 Mac 测试版未经公证。按<a href="./01-getting-started.html#macos-首次启动-绕过-gatekeeper-拦截">首次启动的 Gatekeeper 放行步骤</a>为应用单独放行。系统版本或架构不匹配不能靠放行解决，请先检查安装要求。</p><h3 id="无法确认项目设置" tabindex="-1">无法确认项目设置 <a class="header-anchor" href="#无法确认项目设置" aria-label="Permalink to &quot;无法确认项目设置&quot;">​</a></h3><p>检查是否仍在导入，或是否存在无集数、重复集数、缺失文件、无匹配、多候选和导入错误。合法低置信结果只要求复核，不单独阻止确认。</p><h3 id="项目已在其他窗口打开" tabindex="-1">项目已在其他窗口打开 <a class="header-anchor" href="#项目已在其他窗口打开" aria-label="Permalink to &quot;项目已在其他窗口打开&quot;">​</a></h3><p>同一个项目不能由两个活动实例同时打开。回到原窗口正常关闭项目后重试；不同项目可以分别打开。</p><h3 id="视频缺失" tabindex="-1">视频缺失 <a class="header-anchor" href="#视频缺失" aria-label="Permalink to &quot;视频缺失&quot;">​</a></h3><p>字幕仍可编辑。打开 <strong>项目设置</strong> 重新导入视频并修正集数映射。不要通过把一个视频映射到多个集来绕过缺失提示。</p><h3 id="拼写检查不可用" tabindex="-1">拼写检查不可用 <a class="header-anchor" href="#拼写检查不可用" aria-label="Permalink to &quot;拼写检查不可用&quot;">​</a></h3><p>打开词典目录，确认词典子文件夹同时包含来自同一套 Hunspell 词典的 <code>index.aff</code> 和 <code>index.dic</code>，刷新并选择该词典。完整目录结构和格式说明见<a href="./05-quality-checks.html#安装和切换拼写词典">安装和切换拼写词典</a>。</p><h3 id="机器翻译无法运行" tabindex="-1">机器翻译无法运行 <a class="header-anchor" href="#机器翻译无法运行" aria-label="Permalink to &quot;机器翻译无法运行&quot;">​</a></h3><p>确认正在使用项目模式、已经导入字幕、至少有一个启用的服务预设、集数范围有效，并检查 Base URL、API Key、模型和代理。</p><h3 id="字幕无法导出" tabindex="-1">字幕无法导出 <a class="header-anchor" href="#字幕无法导出" aria-label="Permalink to &quot;字幕无法导出&quot;">​</a></h3><p>检查授权状态、工作区是否有行、ASS 源模板、输出文件名冲突和输出目录权限。授权相关提示见<a href="./09-license-management.html#解决授权问题">解决授权问题</a>。</p><h3 id="更新失败" tabindex="-1">更新失败 <a class="header-anchor" href="#更新失败" aria-label="Permalink to &quot;更新失败&quot;">​</a></h3><p>确认网络连接后重试手动检查。安装失败时保留当前版本，不要删除项目文件；记录错误并在需要时导出诊断包。</p>',59)])])}const q=e(n,[["render",s]]);export{m as __pageData,q as default};
